variante_1.css:
.sl-card-horizontal {
  background-color: var(--sl-card-bg);
  border: 1px solid var(--sl-border);
  color: var(--sl-text-main);
}
.sl-card-horizontal .sl-card-img-ratio {
  width: 100%;
  aspect-ratio: var(--sl-img-aspect-ratio, 4/3);
  object-fit: cover;
}
.sl-card-horizontal .card-body {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.sl-card-horizontal .card-title a {
  color: var(--sl-text-main);
  transition: color 0.2s ease-in-out;
}
.sl-card-horizontal .card-title a:hover {
  color: var(--sl-primary);
}
.sl-card-horizontal .text-body-secondary {
  color: var(--sl-text-main) !important;
  opacity: 0.7;
}

