variante_3.css:
.sl-card-overlay {
  background-color: var(--sl-card-bg);
  border: 1px solid var(--sl-border);
  color: var(--sl-text-main);
}
.sl-card-overlay .sl-card-img-ratio {
  width: 100%;
  aspect-ratio: var(--sl-img-aspect-ratio, 3/2);
  object-fit: cover;
}
.sl-card-overlay .sl-category-overlay {
  background-color: var(--sl-primary);
  color: #fff;
  font-size: 0.85em;
  font-weight: 600;
  transition: background-color 0.2s ease-in-out;
}
.sl-card-overlay .sl-category-overlay a {
  color: inherit;
  text-decoration: none;
}
.sl-card-overlay .sl-category-overlay a:hover {
  text-decoration: underline;
}
.sl-card-overlay .card-title a {
  color: var(--sl-text-main);
  transition: color 0.2s ease-in-out;
}
.sl-card-overlay .card-title a:hover {
